contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool _flag) public payable {
        // _flag is an arbitrary input to quantify over
        // record observable values before
        uint beforeC = address(c).balance;
        bytes32 beforeCodehash = address(c).codehash;
        bool reverted;
        // perform the state-changing call as a top-level statement and capture revert
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // read observables after
        uint afterC = address(c).balance;
        bytes32 afterCodehash = address(c).codehash;
        // If the call does not revert then C's balance must be zero and the codehash must be unchanged
        assert(reverted || (afterC == 0 && afterCodehash == beforeCodehash));
    }
    receive() external payable {}
}

