pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool _flag) internal {
        uint beforeC = address(c).balance;
        bytes32 beforeCodehash = address(c).codehash;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        bytes32 afterCodehash = address(c).codehash;
        assertTrue(reverted || (afterC == 0 && afterCodehash == beforeCodehash));
    }

    function testFuzz_run(bool _flag) public {
        _run(_flag);
    }

    receive() external payable {}
}
